-- Study Abroad country content, BATCH 22: Algeria, Botswana, Zimbabwe, Namibia, Senegal, Cameroon, Angola, Mozambique, Bhutan.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('algeria', 'botswana', 'zimbabwe', 'namibia', 'senegal', 'cameroon', 'angola', 'mozambique', 'bhutan'));
UPDATE countries SET why_title = 'Why study in Algeria?', why_body = '<p>Algeria offers a large public university system with French- and Arabic-taught degrees at moderate set fees for international students, and bilateral scholarships.<ul><li>Large public university system</li><li>Strong in engineering, medicine and sciences</li><li>Low living costs</li><li>Scholarships mostly through bilateral agreements</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students need a <strong>student visa</strong> tied to enrolment at an approved institution, then a <strong>residence card</strong> after arrival.</p><ul><li>Acceptance letter from an Algerian institution</li><li>Scholarship letter or proof of funds, plus the visa fee</li><li>Residence card file: medical certificate, housing contract and enrolment certificate</li><li>Student status does not lead to permanent residence; no post-study route found</li><li>Part-time work is reported as allowed; confirm locally</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Algerian embassy or consulate and the Study in Algeria platform site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>International students apply through the national platform or directly to universities.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French or Arabic language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>The ministry sets annual fees for international students in US dollars.</p><ul><li>2025-26 guide table: from US$800 (bachelor''s in social sciences) to US$4,500 (medical residency)</li><li>Scholarships are limited and mostly bilateral</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> French or Arabic proof depending on programme</li></ul>' WHERE slug = 'algeria';
UPDATE countries SET why_title = 'Why study in Botswana?', why_body = '<p>Botswana is a stable, English-medium Southern African country with the University of Botswana and strong wildlife, tourism and mining sectors.<ul><li>English-medium teaching</li><li>Stable, peaceful country</li><li>Strengths in mining, tourism, environment and health</li><li>Lower cost than many destinations</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Botswana does not issue a separate study permit: the <strong>residence permit</strong> is the study permit, processed after admission and registration. The government study visa page lists extra documents, so confirm which apply.</p><ul><li>Letter of acceptance and proof of sponsorship</li><li>Residence permit processed after registration at the University of Botswana</li><li>Two recent colour passport photos, a flight itinerary and a local address</li><li>UB''s international office helps with the permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Botswana immigration authorities and the University of Botswana site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Motivation letter for postgraduate programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UB charges per credit; annual figures are estimates.</p><ul><li>UB 2026/27 estimates for students from outside Africa: about BWP 56,100 a year (most faculties) and BWP 74,700 (science and engineering), per a third-party guide; African students pay less</li><li>Self-sponsored students pay at least 25% of semester fees before registration</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'botswana';
UPDATE countries SET why_title = 'Why study in Zimbabwe?', why_body = '<p>Zimbabwe has well-established universities teaching in English, with low fees compared with many regions, and strengths in agriculture, health and engineering.<ul><li>English-medium teaching</li><li>Established universities such as the University of Zimbabwe</li><li>Low tuition</li><li>Close to Victoria Falls and national parks</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>International students need a <strong>study permit</strong>, issued for up to one year at a time. The permit can be processed on arrival at the discretion of the Department of Immigration.</p><ul><li>Official acceptance letter (MSU asks for two)</li><li>Study permit fee reported at US$200 at UZ and MSU (October 2026); renewal needs a continuity letter and results</li><li>Two passport photos</li><li>No work rights on a study permit; no post-study work route found</li><li>Proof-of-funds claims such as US$5,000 are unverified</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Zimbabwe Department of Immigration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Letter of acceptance for the permit</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UZ does not publish international fees online; ask the International Relations Office.</p><ul><li>Africa University: about US$1,995 a semester (October 2026)</li><li>Solusi University: about US$990 a semester for undergraduate study</li><li>Aggregator range: US$1,000-$5,000 a year</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'zimbabwe';
UPDATE countries SET why_title = 'Why study in Namibia?', why_body = '<p>Namibia offers English-medium degrees at UNAM and NUST in a stable country with strengths in mining, tourism, agriculture and natural resource management.<ul><li>English-medium teaching</li><li>Stable, safe country</li><li>Strengths in mining, environment and tourism</li><li>Spectacular landscapes</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>All international students (SADC and non-SADC) need a valid <strong>Study Permit</strong>, with fees paid to the Ministry of Home Affairs.</p><ul><li>Admission letter, proof of registration and high school results</li><li>Valid medical aid (UNAM offers an option for international students)</li><li>Permit fee reported at NAD 2,200 for senior students</li><li>Documents in English or officially translated</li><li>NUST warns that failing to comply may lead to deregistration</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Namibian Ministry of Home Affairs and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university; UNAM extended its 2026 applications to 6 February 2026.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Proof of medical aid</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UNAM fee levels differ for SADC and non-SADC students.</p><ul><li>UNAM 2026 minimum payment at registration: NAD 20,775 for non-SADC (including tuition deposit of NAD 14,300 and international levy of NAD 3,500); NAD 12,125 for SADC; NAD 6,975 for Namibians</li><li>Postgraduate and class fees for non-SADC students are double the Namibian rate</li><li>NUST fees were not found; check its 2027 guide</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'namibia';
UPDATE countries SET why_title = 'Why study in Senegal?', why_body = '<p>Senegal is a stable French-speaking West African country with the Cheikh Anta Diop University in Dakar, a regional hub for study, with strengths in humanities, medicine and law.<ul><li>Stable democracy in West Africa</li><li>French-medium education</li><li>Strong in medicine, law and humanities</li><li>Dakar as a regional hub</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Senegal does not publish one standard student visa page. Students usually get an entry permit and then complete residence formalities, often a <strong>foreigner''s identity card (carte d''étranger)</strong>, after arrival.</p><ul><li>Invitation or admission letter from the university</li><li>Visa fee conflicts across sources (about €50, or XOF 80); check the diplomatie.sn portal</li><li>Residence formalities after arrival</li><li>Graduates who stay must apply for a residence permit or work visa</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Senegalese embassy or consulate (diplomatie.sn) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution; requirements vary by school.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Attestation and transcript from the baccalauréat office where applicable</li><li>Passport copy and photographs</li><li>Motivation letter for postgraduate programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official UCAD fee schedule was found.</p><ul><li>Public university range: about XOF 50,000-200,000 a year (guide); another estimates US$1,000-$3,000</li><li>Private universities charge much more</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'senegal';
UPDATE countries SET why_title = 'Why study in Cameroon?', why_body = '<p>Cameroon is a bilingual (English and French) Central African country with public universities in Yaoundé and Buea and a large student population.<ul><li>Bilingual English and French education</li><li>Large public university system</li><li>Strong in medicine, agriculture and humanities</li><li>Low tuition</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A <strong>student visa</strong> from a Cameroonian embassy or consulate is needed to register at a university, applied for through the e-visa portal; there is no visa on arrival at Yaoundé or Douala.</p><ul><li>Admission and invitation letter from the university cooperation office</li><li>Application through the official e-visa portal</li><li>Passport, photographs and proof of funds</li><li>Check current rules with the embassy; no official 2026 rules were found</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Cameroonian embassy (e-visa portal) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>English or French proof</li><li>Entrance requirements per programme</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>International undergraduate fees are not widely published.</p><ul><li>University of Buea: 50,000 FCFA for Cameroonian undergraduates; international undergraduate fee not published; graduate programmes reported at 450,000 FCFA for international students</li><li>Yaoundé I: no fee figure found</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (GCE A-level or baccalauréat)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or French proof depending on programme</li></ul>' WHERE slug = 'cameroon';
UPDATE countries SET why_title = 'Why study in Angola?', why_body = '<p>Angola is a Portuguese-speaking Southern African country with Agostinho Neto University and a growing set of public and private universities, strong in petroleum, engineering and health.<ul><li>Portuguese-medium education</li><li>Energy and petroleum sector</li><li>Public and private universities</li><li>Close links with Portugal and Brazil</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students are accepted first and then apply for a <strong>study visa</strong> at an Angolan embassy or consulate. The visa must be used within 60 days of issue (London consulate guidance).</p><ul><li>Invitation letter from the institution and proof of funds</li><li>Application form, passport, photographs, proof of liquidity, police clearance and medical certificate</li><li>Overstay fines of AOA 15,000 a day are reported by GOV.UK</li><li>The 2026/27 academic year opened on 2 October 2026 (MESCTI)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Angolan consulate and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Each public university runs its own entrance exams for a limited number of places.</p><ul><li>Academic transcripts and certificates</li><li>Portuguese language proof</li><li>Entrance exam at public universities</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official international tuition figures were found.</p><ul><li>Aggregators: public range roughly free to US$500 a year; private US$2,000-$8,000</li><li>Request fees from the institution in writing</li><li>Living costs: about US$600-$1,200 a month (estimate; Luanda is expensive)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Portuguese proof for Portuguese-taught programmes</li></ul>' WHERE slug = 'angola';
UPDATE countries SET why_title = 'Why study in Mozambique?', why_body = '<p>Mozambique is a Portuguese-speaking East African country with Eduardo Mondlane University in Maputo and growing universities in agriculture, engineering and health.<ul><li>Portuguese-medium education</li><li>Eduardo Mondlane University as the leading public university</li><li>Strengths in agriculture, engineering and marine science</li><li>Indian Ocean coastline</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A <strong>student visa</strong> is needed to stay and study; apply at a Mozambican embassy or consulate after acceptance. The visa does not allow employment.</p><ul><li>Admission letter from the institution</li><li>Passport, photographs and proof of funds (an unofficial source cites about US$5,000)</li><li>Visa does not permit employment</li><li>No official 2026 guidance was found; confirm with the embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Mozambican embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>Portuguese language proof</li><li>Entrance exam at public universities</li><li>Passport copy and photographs</li><li>Motivation letter for postgraduate programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition claims conflict between sources.</p><ul><li>One blog says UEM charges about US$1,850 a year to all students; uniRank lists fees as not reported</li><li>International students may pay different rates; ask the international office</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Portuguese proof for Portuguese-taught programmes</li></ul>' WHERE slug = 'mozambique';
UPDATE countries SET why_title = 'Why study in Bhutan?', why_body = '<p>Bhutan is a small Himalayan country known for Gross National Happiness, with the Royal University of Bhutan and affiliated colleges offering English-medium degrees in environment, business, education and health.<ul><li>English-medium teaching</li><li>Environmental and sustainability focus</li><li>Safe, peaceful country</li><li>Small, close-knit colleges</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The Department of Immigration''s 2026 student visa guideline takes effect from 1 May 2026. The recognised institution normally files the visa for foreign students.</p><ul><li>Institution must be recognised by the Royal Government of Bhutan</li><li>Application and proof of enrolment filed by the college</li><li>Indian nationals are reported to receive an entry permit rather than a visa; check the guideline</li><li>Work needs separate authorisation; no post-study work route published</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Bhutan Department of Immigration and your college site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each college; full-time programmes reportedly take applications from March to May.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Application fee reported at US$100 (non-refundable)</li><li>Passport copy and photographs</li><li>Motivation letter for postgraduate programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees conflict across sources.</p><ul><li>Royal Thimphu College: US$3,180 per semester for international full-degree students</li><li>A secondary guide gives Nu. 316,324-370,396 a year (SAARC Nu. 158,162-185,198) for 2026-27 undergraduate tuition (unconfirmed)</li><li>RTC offers no scholarships to international students</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'bhutan';
COMMIT;
